// ✅ Get ALL incoming data as one flat array
const allInputs = $input.all();

// Separate Drive files vs Sheet rows by their structure
const driveInput = [];
const sheetInput = [];

// Loop through all incoming items and detect source
for (const item of allInputs) {
  const data = item.json;

  // Drive files have `id` + `name`
  if (data.id && data.name) {
    driveInput.push(data);
  }

  // Sheet rows have `ID` + `Name`
  if (data.ID || data.Name) {
    sheetInput.push(data);
  }
}

// ✅ Extract already processed IDs from sheet
const processedIds = sheetInput
  .filter(row => row.ID && row.ID !== "")
  .map(row => row.ID);

// ✅ Collect only new files not already in the sheet
const newFiles = driveInput.filter(f =>
  !processedIds.includes(f.id));

// ✅ Debug info
console.log(`Drive files found: ${driveInput.length}`);
console.log(`Sheet rows found: ${sheetInput.length}`);
console.log(`Already processed IDs: ${processedIds.length}`);
console.log(`New files to download: ${newFiles.length}`);

// ✅ Output only the new ones
return newFiles.map(f => ({
  json: {
    fileId: f.id,
    fileName: f.name
  }
}));

const items = query.items || [];
let breakdown = [];
let total = 0;
for (const it of items) {
  const lineTotal = Number(it.quantity) * Number(it.unit_price);
  total += lineTotal;
  breakdown.push(`${it.quantity} x ${it.name} @ ${it.unit_price} = ${lineTotal}`);
}
return JSON.stringify({ breakdown, grand_total: total });

